// Backwards-compatible flattened view for legacy cache consumers.
export const sampleVendorSites = sampleVendorSitesResponse.suppliers.flatMap((supplier) => {
	const header = supplier?.supplier_header ?? {};
	const supplierSites = Array.isArray(supplier?.supplier_sites) ? supplier.supplier_sites : [];

	return supplierSites.map((site) => ({
		address_purpose: String(site?.address_purpose ?? '').trim(),
		id: String(site?.vendor_site_id ?? ''),
		name: String(header?.supplier_name ?? '').trim(),
		address: [site?.address_line_1, site?.address_line_2, site?.address_line_3]
			.map((part) => String(part ?? '').trim())
			.filter(Boolean)
			.join(' '),
		city: String(site?.city ?? '').trim(),
		state: String(site?.state ?? site?.province ?? '').trim(),
		zip: String(site?.postal_code ?? '').trim(),
		country: String(site?.country ?? '').trim(),
		status: String(header?.supplier_status ?? '').trim(),
		status_details: String(header?.supplier_status_details ?? '').trim()
	}));
});
